#include <bits/stdc++.h>
using namespace std;
#define ULL unsigned long long
int main() {
    ios::sync_with_stdio(0), cin.tie(0);
    int a, b, c, d, e, n;
    if (!(cin >> a >> b >> c >> d >> e >> n)) return 0;
    vector<int> v(n);
    auto RAND = [s = (ULL)a, b, c](int L, int R) mutable -> int {
        return s = (b * s + c) % (1LL << 31), L + (s % (R - L + 1));
    };
    auto H = [](const vector<int>& arr, ULL h = 131452077) -> ULL {
        return for_each(arr.begin(), arr.end(), [&](int x) { h = h * 911382629ULL + (x + 1000007); }), h;
    };
    generate(v.begin(), v.end(), [&]() { return RAND(d, e); });
    
    // 原地归并排序核心
    auto R = [&](int l, int r) { for (; l < r; swap(v[l++], v[r--])); };
    auto M = [&](auto& self, int l, int m, int r) -> void {
        int i = l, j = m + 1, k;
        while (i <= m && j <= r)
            if (v[i] <= v[j]) i++;
            else {
                for (k = j; j <= r && v[j] < v[i]; j++);
                R(i, m), R(m + 1, j - 1), R(i, j - 1);
                i += j - k, m += j - k;
            }
    };
    auto S = [&](auto& self, int l, int r) -> void {
        if (l < r) { int m = l + (r - l) / 2; self(self, l, m), self(self, m + 1, r), M(M, l, m, r); }
    };
    S(S, 0, n - 1);

    cout << H(v) << "\n";
    return 0;
}
